<?php
namespace App\Domain\Verification\Services;
use App\Domain\Documents\Enums\DocumentStatus;use App\Domain\Verification\Enums\{VerificationStage,VerificationStatus};use App\Models\{Document,DocumentVerification,VerificationHistory};use Illuminate\Support\Facades\DB;use RuntimeException;
class VerificationWorkflow{public function currentOrCreate(Document $document,VerificationStage $stage):DocumentVerification{if(!$document->current_version_id)throw new RuntimeException('Document has no current version.');return DocumentVerification::firstOrCreate(['document_id'=>$document->id,'document_version_id'=>$document->current_version_id,'stage'=>$stage],['status'=>VerificationStatus::Pending]);}public function assign(DocumentVerification $verification,int $officerId,int $actorId):void{DB::transaction(function()use($verification,$officerId,$actorId){$this->history($verification,'ASSIGNED',$verification->status->value,$verification->status->value,$actorId,null,null,['assigned_to'=>$officerId]);$verification->update(['assigned_to'=>$officerId,'assigned_by'=>$actorId,'assigned_at'=>now()]);});}public function start(DocumentVerification $verification,int $actorId):void{$this->assertAssignedOrUnassigned($verification,$actorId);$old=$verification->status->value;$verification->update(['status'=>VerificationStatus::InReview,'started_at'=>$verification->started_at??now(),'assigned_to'=>$verification->assigned_to??$actorId,'assigned_at'=>$verification->assigned_at??now()]);$this->history($verification,'STARTED',$old,VerificationStatus::InReview->value,$actorId);}public function approve(DocumentVerification $verification,int $actorId,?string $remarks=null):void{$this->assertAssignedOrUnassigned($verification,$actorId);$document=$verification->document()->lockForUpdate()->firstOrFail();if($verification->document_version_id!==$document->current_version_id)throw new RuntimeException('Only the current document version may be approved.');if($verification->version->created_by===$actorId)throw new RuntimeException('Maker-checker rule: the creator/uploader of this version cannot approve it.');DB::transaction(function()use($verification,$document,$actorId,$remarks){$old=$verification->status->value;$verification->update(['status'=>VerificationStatus::Approved,'decision'=>'APPROVED','decision_by'=>$actorId,'decision_at'=>now(),'remarks'=>$remarks]);$next=match($verification->stage){VerificationStage::QualityCheck=>DocumentStatus::PendingVerification,VerificationStage::DocumentVerification=>DocumentStatus::Verified,VerificationStage::FinalApproval=>DocumentStatus::Approved};$from=$document->status->value;$document->update(['status'=>$next]);$this->history($verification,'APPROVED',$old,VerificationStatus::Approved->value,$actorId,null,$remarks);DB::table('document_status_history')->insert(['document_id'=>$document->id,'from_status'=>$from,'to_status'=>$next->value,'reason'=>$verification->stage->value.' approved','changed_by'=>$actorId,'changed_at'=>now(),'created_at'=>now()]);if($verification->stage===VerificationStage::DocumentVerification)$this->currentOrCreate($document,VerificationStage::FinalApproval);if($verification->stage===VerificationStage::FinalApproval){$document->update(['status'=>DocumentStatus::Available]);DB::table('document_status_history')->insert(['document_id'=>$document->id,'from_status'=>DocumentStatus::Approved->value,'to_status'=>DocumentStatus::Available->value,'reason'=>'Final approval completed; available for authorized retrieval','changed_by'=>$actorId,'changed_at'=>now(),'created_at'=>now()]);}});}public function reject(DocumentVerification $verification,int $actorId,string $reasonCode,string $remarks):void{$this->assertAssignedOrUnassigned($verification,$actorId);if(trim($remarks)==='')throw new RuntimeException('Rejection remarks are required.');DB::transaction(function()use($verification,$actorId,$reasonCode,$remarks){$document=$verification->document()->lockForUpdate()->firstOrFail();$old=$verification->status->value;$verification->update(['status'=>VerificationStatus::Rejected,'decision'=>'REJECTED','decision_by'=>$actorId,'decision_at'=>now(),'reason_code'=>$reasonCode,'remarks'=>$remarks]);$next=$verification->stage===VerificationStage::QualityCheck?DocumentStatus::QcRejected:DocumentStatus::VerificationRejected;$from=$document->status->value;$document->update(['status'=>$next]);$this->history($verification,'REJECTED',$old,VerificationStatus::Rejected->value,$actorId,$reasonCode,$remarks);DB::table('document_status_history')->insert(['document_id'=>$document->id,'from_status'=>$from,'to_status'=>$next->value,'reason'=>$reasonCode.': '.$remarks,'changed_by'=>$actorId,'changed_at'=>now(),'created_at'=>now()]);});}private function assertAssignedOrUnassigned(DocumentVerification $v,int $actorId):void{if($v->assigned_to&&$v->assigned_to!==$actorId)throw new RuntimeException('This verification is assigned to another officer.');}private function history(DocumentVerification $v,string $action,?string $old,string $new,int $actor,?string $reason=null,?string $remarks=null,array $context=[]):void{VerificationHistory::create(['document_verification_id'=>$v->id,'action'=>$action,'previous_status'=>$old,'new_status'=>$new,'reason_code'=>$reason,'remarks'=>$remarks,'performed_by'=>$actor,'performed_at'=>now(),'ip_address'=>request()->ip(),'request_id'=>request()->attributes->get('request_id'),'context'=>$context?:null]);}}
